327:     const indexes = game.value.cells.filter((cell) => cell.origin !== 'GIVEN' && cell.value === 0).map((cell) => cell.index)
328:     if (!indexes.length) return
329:     const before = capture(indexes)
330:     const board = currentBoard(true)
331:     for (const index of indexes) game.value.cells[index].notesMask = getCandidateMask(board, index)
