336:   function requestHint(): HintResult | null {
337:     if (!game.value || game.value.status !== 'PLAYING') return null
338:     if (pendingHint.value) return pendingHint.value
339:     const wrong = game.value.cells.find(c => c.origin !== 'GIVEN' && c.value !== 0 && c.value !== c.solution)
340:     if (wrong) {
341:       pendingHint.value = { index: wrong.index, digit: wrong.solution, technique: 'BACKTRACKING', message: `第 ${Math.floor(wrong.index / 9) + 1} 行第 ${wrong.index % 9 + 1} 列的填写有误，请先检查这个格。展开答案可以更正。`, focusIndexes: [wrong.index] }
342:     } else {
343:       pendingHint.value = findHint(currentBoard(true))
344:       if (!pendingHint.value) {
